-- name: InsertBrowserAuthToken :one
-- Team scope: minted when a member clicks "Open browser".
INSERT INTO browser_auth_tokens (id, team_id, browser_id, user_id, token_hash, expires_at)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('browser_id'), sqlc.arg('user_id'), sqlc.arg('token_hash'), sqlc.arg('expires_at'))
RETURNING *;

-- name: ConsumeBrowserAuthToken :one
-- System scope: forward_auth's exchange. Only a row that is unused and unexpired is returned and
-- marked used in the same statement, so a replayed token — used or raced — is refused.
UPDATE browser_auth_tokens SET used_at = now(), updated_at = now()
WHERE token_hash = sqlc.arg('token_hash') AND used_at IS NULL AND expires_at > now()
RETURNING *;

-- name: DeleteBrowserAuthTokensOfBrowser :exec
-- Team scope: cascades when a browser is removed.
DELETE FROM browser_auth_tokens WHERE browser_id = sqlc.arg('browser_id') AND team_id = sqlc.arg('team_id');
